MATCH (acc:FlightAccident)
WHERE EXISTS { MATCH (acc)-[:involves]->(:AircraftModel {name: "L-410 Turbolet"}) }
   OR EXISTS { MATCH (acc)-[:departsFrom]->(:Airport {name: "Ramón Villeda Morales International Airport"}) }
RETURN acc.name AS accident_name;

MATCH (model:AircraftModel)
WHERE (
        (model)-[:manufacturedBy]->(:AircraftManufacturer {name: 'LET Aircraft Industries'})
    )
   OR (
        (model)<-[:involves]-(:FlightAccident {name: 'Parachute Kemerovo Let L-410UVP-E crash'})
    )
RETURN model.name AS aircraft_model_name;
